def expand_range_key(key, value, width):
    m = RANGE_RE.match(str(key))
    if not m:
        return None
    a = int(m.group(1))
    b = int(m.group(2))
    out = {}
    step = 1 if a <= b else -1
    for i in range(a, b + step, step):
        if 0 <= i <= TIME_MAX:
            k = zero_pad(i) if width == 2 else str(i)
            out[k] = value
    return out

