QTreeWidgetItem* findFieldItem( QTreeWidgetItem* root, const QString& name )
{
    if ( !root ) {
        return nullptr;
    }
    for ( int i = 0; i < root->childCount(); ++i ) {
        auto* child = root->child( i );
        if ( child->text( 0 ) == name ) {
            return child;
        }
        if ( auto* nested = findFieldItem( child, name ) ) {
            return nested;
        }
    }
    return nullptr;
}

