QTreeWidgetItem* findChildItem( QTreeWidgetItem* parent, const QString& name )
{
    if ( !parent ) {
        return nullptr;
    }
    for ( int i = 0; i < parent->childCount(); ++i ) {
        auto* child = parent->child( i );
        if ( child->text( 0 ) == name ) {
            return child;
        }
    }
    return nullptr;
}

