QString absolutePath( const QString& baseDir, const QString& value )
{
    if ( value.isEmpty() ) {
        return {};
    }

    const QFileInfo fileInfo( value );
    return fileInfo.isAbsolute() ? fileInfo.absoluteFilePath()
                                 : QFileInfo( QDir( baseDir ).filePath( value ) ).absoluteFilePath();
}

