    std::lock_guard<std::recursive_mutex> callbackGuard( callbackInvocationMutex() );
    if ( !callbackHolder->active.load( std::memory_order_acquire ) ) {
        return;
    }

    if ( callbackHolder->callback ) {
        callbackHolder->callback( state );
    }
