int clampToInt( qsizetype value )
{
    if ( value > std::numeric_limits<int>::max() ) {
        return std::numeric_limits<int>::max();
    }
    if ( value < std::numeric_limits<int>::min() ) {
        return std::numeric_limits<int>::min();
    }
    return static_cast<int>( value );
}

