QStringList unknownKeys( const QJsonObject& object, const QSet<QString>& knownKeys )
{
    QStringList unknown;
    for ( const auto& key : object.keys() ) {
        if ( !knownKeys.contains( key ) ) {
            unknown.push_back( key );
        }
    }
    return unknown;
}

