QString defaultComLogDirectory()
{
    auto docs = QStandardPaths::writableLocation( QStandardPaths::DocumentsLocation );
    if ( docs.isEmpty() ) {
        docs = QDir::homePath();
    }

    const QString initialDir = QDir( docs ).filePath( QStringLiteral( "kloggs" ) );
    QDir initDir( initialDir );
    if ( !initDir.exists() ) {
        initDir.mkpath( "." );
    }

    return initialDir;
}

