{
    QByteArray output;
    output.reserve( input.size() );
    bool inString = false;
    bool escape = false;
    for ( int i = 0; i < input.size(); ++i ) {
        const char c = input.at( i );
        if ( inString ) {
            output.append( c );
            if ( escape ) {
                escape = false;
                continue;
            }
            if ( c == '\\' ) {
                escape = true;
            }
            else if ( c == '"' ) {
                inString = false;
            }
            continue;
        }

        if ( c == '"' ) {
            inString = true;
            output.append( c );
            continue;
        }

        if ( c == '/' && i + 1 < input.size() && input.at( i + 1 ) == '/' ) {
            while ( i < input.size() && input.at( i ) != '\n' ) {
                ++i;
            }
            if ( i < input.size() && input.at( i ) == '\n' ) {
                output.append( '\n' );
            }
            continue;
        }

        output.append( c );
    }
    return output;
}

