#if _WIN64
inline int countLeadingZeroes( uint64_t value )
{
    unsigned long leading_zero = 0;

    if ( _BitScanReverse64( &leading_zero, value ) ) {
        return 63ul - leading_zero;
    }
    else {
        return 64;
    }
}
