namespace {

int mapPullToFollowLength( int length );

int intLog2( uint64_t x )

int mapPullToFollowLength( int length );

int intLog2( uint64_t x )
{
    return 63 - countLeadingZeroes( x | 1 );
}

// see https://lemire.me/blog/2021/05/28/computing-the-number-of-digits-of-an-integer-quickly/

// see https://lemire.me/blog/2021/05/28/computing-the-number-of-digits-of-an-integer-quickly/
int countDigits( uint64_t x )
{
    int l2 = intLog2( x );
    int ans = ( ( 77 * l2 ) >> 8 );
    static uint64_t table[] = { 9,
                                99,
                                999,
                                9999,
                                99999,
                                999999,
                                9999999,
                                99999999,
                                999999999,
                                9999999999,
                                99999999999,
                                999999999999,
                                9999999999999,
                                99999999999999,
                                999999999999999,
                                9999999999999999,
                                99999999999999999,
                                999999999999999999,
                                9999999999999999999u,
                                0xFFFFFFFFFFFFFF };
    if ( x > table[ ans ] ) {
        ans += 1;
    }
    return ans + 1;
}

