uint32_t buildPatternCombination( std::string_view variables )

}

uint32_t buildPatternCombination( std::string_view variables )
{
    uint32_t combination = 0;
    for ( auto bit = 0u; bit < variables.size(); ++bit ) {
        if ( variables[ bit ] ) {
            combination = combination | ( 1u << bit );
        }
    }

    return combination;
}

