QString readableSize( uint64_t size )
{
    static const std::array<std::tuple<uint64_t, uint64_t, QString>, 5> sizeSteps
        = { std::make_tuple( 0x10000000000ull, 30ull, QObject::tr( "TiB" ) ),
            std::make_tuple( 0x40000000ull, 20ull, QObject::tr( "GiB" ) ),
            std::make_tuple( 0x100000ull, 10ull, QObject::tr( "MiB" ) ),
            std::make_tuple( 0x400ull, 0ull, QObject::tr( "KiB" ) ) };

    QLocale defaultLocale;
    QString outputFormat{ "%1 %2" };

    const auto sizeStep
        = std::find_if( sizeSteps.cbegin(), sizeSteps.cend(),
                        [ &size ]( const auto& step ) { return size >= std::get<0>( step ); } );

    if ( sizeStep != sizeSteps.end() ) {
        const auto humanSize = static_cast<double>( ( size >> std::get<1>( *sizeStep ) ) ) / 1024.0;
        return outputFormat.arg( defaultLocale.toString( humanSize, 'f', 2 ),
                                 std::get<2>( *sizeStep ) );
    }
    else {
        return outputFormat.arg( defaultLocale.toString( static_cast<qulonglong>( size ) ),
                                 QObject::tr( "B" ) );
    }
}

};

PartialSearchResults filterLines( const PatternMatcher& matcher, const LogData::RawLines& rawLines,
                                  LineNumber chunkStart )
{
    LOG_DEBUG << "Filter lines at " << chunkStart;
    PartialSearchResults results;
    results.chunkStart = chunkStart;
    results.processedLines = LinesCount{ rawLines.endOfLines.size() };

    const auto& lines = rawLines.buildUtf8View();

    for ( auto offset = 0u; offset < lines.size(); ++offset ) {
        const auto& line = lines[ offset ];

        const auto hasMatch = matcher.hasMatch( line );

        if ( hasMatch ) {
            results.maxLength = qMax( results.maxLength, getUntabifiedLength( line ) );
            const auto lineNumber = chunkStart + LinesCount{ offset };
            results.matchingLines.add( lineNumber.get() );

            // LOG_INFO << "Match at " << lineNumber << ": " << line;
        }
    }
    return results;
}

